.row {
  display: flex;
  flex-wrap: wrap;
  padding: 0 4px;
}
.column {
  flex: 25%;
  max-width: 25%;
  padding: 0 4px;
}

@media screen and (max-width: 800px) {
  .column {
    flex: 50%; max-width: 50%;
  }
}
@media screen and (max-width: 600px) {
  .column {
    flex: 100%; max-width: 100%;
  }
}
